import re, glob, os
from datetime import date, timedelta

REF = date(2025, 8, 12)

def d(s):
    y,m,d_ = map(int, s.split('-'))
    return date(y,m,d_)

files = sorted(glob.glob('/app/logs/*.log'))
counts = {}  # period -> {sev: count}
sev_re = re.compile(r'^(\d{4}-\d{2}-\d{2}) \d{2}:\d{2}:\d{2} \[(ERROR|WARNING|INFO|DEBUG)\]')

all_sev = {}
for f in files:
    day = d(f.split('/')[-1].split('_')[0])
    for line in open(f):
        line = line.rstrip('\n')
        m = sev_re.match(line)
        if not m: continue
        sev = m.group(2)
        all_sev.setdefault(day, {}).setdefault(sev, 0)
        all_sev[day][sev] += 1

def cnt(day, sev):
    return all_sev.get(day, {}).get(sev, 0)

def range_days(start, end):
    d_ = start
    while d_ <= end:
        yield d_
        d_ += timedelta(days=1)

def period_counts(period):
    res = {'ERROR':0,'WARNING':0,'INFO':0}
    if period == 'today':
        days = [REF]
    elif period == 'last_7_days':
        days = list(range_days(REF - timedelta(days=6), REF))
    elif period == 'last_30_days':
        days = list(range_days(REF - timedelta(days=29), REF))
    elif period == 'month_to_date':
        days = list(range_days(date(2025,8,1), REF))
    else:  # total
        days = sorted(all_sev)
    for day in days:
        for sev in res:
            res[sev] += cnt(day, sev)
    return res

out_lines = ['period,severity,count']
for period in ['today','last_7_days','last_30_days','month_to_date','total']:
    for sev in ['ERROR','WARNING','INFO']:
        c = period_counts(period)[sev]
        out_lines.append(f'{period},{sev},{c}')

with open('/app/summary.csv','w') as f:
    f.write('\n'.join(out_lines) + '\n')

# debug print of per-day data around ranges
for day in sorted(all_sev):
    print(day, all_sev[day])
